using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ScoreXPItemDataList", menuName = "Data/ScoreXP/ScoreXPItemDataList")]
public class ScoreXPItemDataList : ScriptableObject
{
	[SerializeField]
	private List<ScoreXPItemData> scoreXPItemDatas = new List<ScoreXPItemData>();

	public ScoreXPItemData GetScoreXPItemData(string scoreXPItemDataName)
	{
		string text = scoreXPItemDataName.Replace(" ", "").ToLower();
		for (int i = 0; i < scoreXPItemDatas.Count; i++)
		{
			if (text == scoreXPItemDatas[i].name.ToLower())
			{
				return scoreXPItemDatas[i];
			}
		}
		return null;
	}
}
